// The user is the connection's, never the frame's: the validator has already stripped any userId a client sent.
async function answerListSessions(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore | undefined,
  {limit, before}: ListSessionsMessage
): Promise<void> {
  try {
    const summaries = (await sessionStore?.listFor?.(session.userId, {limit, before})) ?? [];
    sendJson(ws, {type: 'session_list', sessions: summaries.map(toSummaryFrame)});
  } catch (error) {
    log.error('ws', 'session list failed', {userId: session.userId, error: messageOf(error)});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list sessions');
  }
}

// A Date does not survive JSON.stringify as a Date, so the wire carries ISO strings.
function toSummaryFrame(summary: SessionSummary): SessionSummaryFrame {
  return {
    sessionId: summary.sessionId,
    createdAt: summary.createdAt.toISOString(),
    updatedAt: summary.updatedAt.toISOString(),
    entryCount: summary.entryCount,
  };
}

function messageOf(error: unknown): string {
  return error instanceof Error ? error.message : 'Unknown error';
}
