// The shared engine authenticates every upgrade as u1.
const startEngine = async (sessionStore: SessionStore): Promise<string> => (await startEngineWith({sessionStore})).url;

// Sends the frame once connected, then a ping whose pong marks that every answer to the frame has arrived.
const answerOn = (client: WebSocket, frame: Frame, outbound: unknown, frames: Frame[]): boolean => {
  if (frame.type === 'pong') return true;
  if (frame.type !== 'connected') {
    frames.push(frame);
    return false;
  }
  client.send(JSON.stringify(outbound));
  client.send(JSON.stringify({type: 'ping', timestamp: 1}));
  return false;
};

const askAfterConnect = async (url: string, outbound: unknown): Promise<{frames: Frame[]}> => {
  const client = connectClient(url);
  const frames: Frame[] = [];
  await new Promise<void>(resolve => {
    client.on('message', raw => {
      if (answerOn(client, JSON.parse(String(raw)) as Frame, outbound, frames)) resolve();
    });
  });
  return {frames};
};

